using System;
using System.Collections;
using System.IO;
using System.Linq;
using System.Reflection;
using NUnit.Framework;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.TestTools;
using UnityEngine.UI;
using Object=UnityEngine.Object;
namespace SpatialSurvivor.Tests {
public class SurvivorArmoryTests {
 [Test]public void WeaponPurchasesChargeOnceAndRejectUnaffordableOrLockedEquip(){var save=new MetaSave{coins=79};Assert.That(save.OwnsWeapon(0));Assert.That(save.BuyWeapon(1),Is.False);Assert.That(save.EquipWeapon(1),Is.False);save.coins=500;Assert.That(save.BuyWeapon(1));Assert.That(save.coins,Is.EqualTo(420));Assert.That(save.equippedWeapon,Is.EqualTo(1));Assert.That(save.BuyWeapon(1),Is.False);Assert.That(save.coins,Is.EqualTo(420));Assert.That(save.EquipWeapon(0));Assert.That(save.BuyWeapon(-1)||save.BuyWeapon(99),Is.False);}
 [Test]public void OldSavesRetainCrystalsAndReceiveFreeWandOnly(){string dir=Path.Combine(Path.GetTempPath(),"SurvivorArmory",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{string path=Path.Combine(dir,"save.json");File.WriteAllText(path,"{\"version\":2,\"crystals\":260,\"levels\":[1,2,0,0,0,0,0,0],\"soundEnabled\":false,\"hapticsEnabled\":true}");var store=new SurvivorProgressStore(path);var save=store.Load(out _);Assert.That(save.crystals,Is.EqualTo(260));Assert.That(save.levels[1],Is.EqualTo(2));Assert.That(save.coins,Is.Zero);Assert.That(save.ownedWeapons,Is.EqualTo(1));Assert.That(save.equippedWeapon,Is.Zero);Assert.That(save.soundEnabled,Is.False);save.coins=400;Assert.That(save.BuyWeapon(2));store.Save(save);save=store.Load(out _);Assert.That(save.coins,Is.EqualTo(260));Assert.That(save.OwnsWeapon(2));Assert.That(save.equippedWeapon,Is.EqualTo(2));}finally{Directory.Delete(dir,true);}}
 [Test]public void InvalidArmoryFieldsAreNormalizedWithoutLosingUpgrades(){string dir=Path.Combine(Path.GetTempPath(),"SurvivorArmory",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{string path=Path.Combine(dir,"save.json");File.WriteAllText(path,"{\"version\":3,\"crystals\":40,\"levels\":[3,0,0,0,0,0,0,0],\"coins\":-5,\"ownedWeapons\":0,\"equippedWeapon\":99}");var save=new SurvivorProgressStore(path).Load(out _);Assert.That(save.coins,Is.Zero);Assert.That(save.equippedWeapon,Is.Zero);Assert.That(save.OwnsWeapon(0));Assert.That(save.levels[0],Is.EqualTo(3));}finally{Directory.Delete(dir,true);}}
 [Test]public void GoldRewardsComeFromPlayAndVictory(){Assert.That(SurvivorArmory.CoinReward(0,0,false),Is.Zero);Assert.That(SurvivorArmory.CoinReward(120,10,false),Is.EqualTo(74));Assert.That(SurvivorArmory.CoinReward(120,10,true),Is.EqualTo(194));Assert.That(SurvivorArmory.CoinReward(-1,-1,false),Is.Zero);}
 [Test]public void CatalogHasRealAssetsAndAllSkillDescriptions(){Assert.That(SurvivorRules.Cards.Length,Is.EqualTo(39));Assert.That(SurvivorBestiary.Creatures.Length,Is.EqualTo(11));foreach(var weapon in SurvivorArmory.Weapons){Assert.That(Resources.Load<GameObject>("Art/Weapons/"+weapon.model),Is.Not.Null);Assert.That(weapon.damage,Is.GreaterThan(0));}foreach(var creature in SurvivorBestiary.Creatures)Assert.That(Resources.Load<GameObject>("Art/Creatures/"+creature.model),Is.Not.Null);foreach(var card in SurvivorRules.Cards){Assert.That(card.description,Is.Not.Empty);if(card.rarity==Rarity.LEGENDARY)Assert.That(SurvivorBestiary.Evolution(card.id),Does.Contain("进化条件"));}}
 [UnityTest]public IEnumerator LibraryShopSettlementAndFlightWorkTogether(){
  EditorSceneManager.OpenScene("Assets/Scenes/SpatialSurvivor.unity");yield return new EnterPlayMode();yield return null;yield return null;var game=Object.FindObjectOfType<SurvivorGame>();game.enabled=false;var ui=game.GetComponent<SurvivorUI>();ui.enabled=false;Assert.That(game.Ready);string dir=Path.Combine(Path.GetTempPath(),"SurvivorArmory",Guid.NewGuid().ToString("N"));var store=new SurvivorProgressStore(Path.Combine(dir,"save.json"));Set(game,"progressStore",store);game.meta=new MetaSave{coins=500};
  foreach(var page in new[]{ScreenState.Skills,ScreenState.Bestiary,ScreenState.Shop}){game.screen=page;Call(ui,"Build");Assert.That(Buttons(ui).Any(b=>b.name=="返回"));if(page!=ScreenState.Skills){Assert.That((RenderTexture)Get(ui,"previewTexture"),Is.Not.Null);Assert.That((GameObject)Get(ui,"previewModel"),Is.Not.Null);}Capture(game,"armory-"+page);}
  Assert.That(game.PurchaseHandWeapon(2));Assert.That(game.meta.coins,Is.EqualTo(360));Assert.That(store.Load(out _).equippedWeapon,Is.EqualTo(2));Assert.That(game.PurchaseHandWeapon(2));Assert.That(game.meta.coins,Is.EqualTo(360));
  string blocker=Path.Combine(dir,"blocked");File.WriteAllText(blocker,"file prevents directory creation");Set(game,"progressStore",new SurvivorProgressStore(Path.Combine(blocker,"save.json")));LogAssert.Expect(LogType.Error,new System.Text.RegularExpressions.Regex("存档失败："));Assert.That(game.PurchaseHandWeapon(3),Is.False);Assert.That(game.meta.coins,Is.EqualTo(360));Assert.That(game.meta.OwnsWeapon(3),Is.False,"Failed purchase save rolls back ownership and funds");Set(game,"progressStore",store);game.saveError="";
  for(int i=0;i<SurvivorRules.Cards.Length;i++){game.screen=ScreenState.Skills;Set(ui,"libraryIndex",i);Call(ui,"Build");Assert.That(Object.FindObjectsOfType<Text>().Any(t=>t.text==SurvivorRules.Cards[i].title));}
  game.screen=ScreenState.Bestiary;Set(ui,"libraryIndex",6);Call(ui,"Build");Capture(game,"armory-flying-codex");
  game.StartRun();Assert.That(game.RunWeapon,Is.EqualTo(2));game.Pause();Call(ui,"OpenLibrary",ScreenState.Shop);Assert.That(game.screen,Is.EqualTo(ScreenState.Shop));Assert.That(game.PurchaseHandWeapon(1));Assert.That(game.RunWeapon,Is.EqualTo(2),"Mid-run purchase cannot replace active weapon");float elapsed=game.player.elapsed;game.Step(1);Assert.That(game.player.elapsed,Is.EqualTo(elapsed));Call(ui,"CloseLibrary");Assert.That(game.screen,Is.EqualTo(ScreenState.Paused));game.Pause();
  game.player.elapsed=120;game.player.kills=10;int coins=game.meta.coins;Call(game,"Finish",false);Assert.That(game.lastCoinReward,Is.EqualTo(74));Assert.That(game.meta.coins,Is.EqualTo(coins+74));game.Menu();game.Menu();Assert.That(game.meta.coins,Is.EqualTo(coins+74),"Settlement cannot repeat on menu/retry");Assert.That(store.Load(out _).coins,Is.EqualTo(coins+74));
  game.StartRun();game.player.elapsed=240;Set(game,"completedBosses",1);game.player.maxHealth=game.player.health=100000;game.player.damage=0;Array.Clear(game.player.stacks,0,game.player.stacks.Length);Set(game,"spawn",100f);var pool=(SurvivorGame.Enemy[])Get(game,"enemies");var flyer=pool[19];Assert.That((bool)Call(game,"Spawn",flyer,5));var start=flyer.go.transform.position;for(int i=0;i<180;i++)game.Step(1/90f);Assert.That(Vector3.Distance(start,flyer.go.transform.position),Is.GreaterThan(.5f));Assert.That(flyer.go.transform.position.y,Is.GreaterThan(game.platform.Navigation.Floor+.5f));Assert.That(game.platform.Navigation.ContainsAir(flyer.go.transform.position,flyer.radius));var pos=flyer.go.transform.position;flyer.freeze=2;game.Step(.5f);Assert.That(flyer.go.transform.position,Is.EqualTo(pos));game.Pause();game.Step(1);Assert.That(flyer.go.transform.position,Is.EqualTo(pos));game.Pause();game.platform.Head.transform.LookAt(flyer.go.transform.position);Capture(game,"armory-flying-combat");
  game.Menu();Object.DestroyImmediate(game.gameObject);Directory.Delete(dir,true);yield return new ExitPlayMode();
 }
 [UnityTest]public IEnumerator EveryHandWeaponDamagesAirTargetsAndFreezesWithPause(){
  EditorSceneManager.OpenScene("Assets/Scenes/SpatialSurvivor.unity");yield return new EnterPlayMode();yield return null;yield return null;var game=Object.FindObjectOfType<SurvivorGame>();game.enabled=false;game.GetComponent<SurvivorUI>().enabled=false;var pool=(SurvivorGame.Enemy[])Get(game,"enemies");
  foreach(var definition in SurvivorArmory.Weapons){game.meta.equippedWeapon=(int)definition.kind;game.StartRun();Set(game,"spawn",100f);game.player.damage=20;Array.Clear(game.player.stacks,0,game.player.stacks.Length);var target=pool[19];Assert.That((bool)Call(game,"Spawn",target,5));target.go.transform.position=new Vector3(0,1.25f,definition.kind==HandWeaponKind.Runeblade?.65f:1.4f);target.hp=target.maxHp=1000;var from=new Vector3(0,1.37f,0);var ray=new Ray(from,Vector3.forward);Assert.That(game.FireHandWeapon(ray),Is.True,definition.name);int before=target.hp;for(int frame=0;frame<45;frame++)Call(game,"HandShotStep",1/90f);Assert.That(target.hp,Is.LessThan(1000),definition.name+" must hit at airborne height");if(definition.kind==HandWeaponKind.FrostStaff)Assert.That(target.slow,Is.EqualTo(2));if(definition.kind==HandWeaponKind.EmberStaff)Assert.That(target.burn,Is.EqualTo(3));Assert.That(game.FireHandWeapon(ray),Is.False,"Cooldown prevents immediate second attack");game.Pause();int pausedHp=target.hp;game.Step(1);Assert.That(target.hp,Is.EqualTo(pausedHp));Assert.That(game.FireHandWeapon(ray),Is.False);game.Pause();}
  game.Menu();yield return new ExitPlayMode();
 }
 [UnityTest]public IEnumerator HandSpellSpecialEffectsAndRoomCollisionMatchShopDescriptions(){
  EditorSceneManager.OpenScene("Assets/Scenes/SpatialSurvivor.unity");yield return new EnterPlayMode();yield return null;yield return null;var game=Object.FindObjectOfType<SurvivorGame>();game.enabled=false;game.GetComponent<SurvivorUI>().enabled=false;var pool=(SurvivorGame.Enemy[])Get(game,"enemies");
  foreach(int kind in new[]{2,3,4,5}){game.meta.equippedWeapon=kind;game.StartRun();Set(game,"spawn",100f);Array.Clear(game.player.stacks,0,game.player.stacks.Length);var points=kind==2||kind==5?new[]{new Vector3(0,1.25f,1),new Vector3(0,1.25f,2),new Vector3(0,1.25f,3),new Vector3(0,1.25f,4)}:new[]{new Vector3(0,1.25f,1.3f),new Vector3(.4f,1.25f,1.3f),new Vector3(-.4f,1.25f,1.3f),new Vector3(1.1f,1.25f,1.3f)};for(int i=0;i<4;i++){Assert.That((bool)Call(game,"Spawn",pool[19+i],5));pool[19+i].go.transform.position=points[i];pool[19+i].hp=1000;}Assert.That(game.FireHandWeapon(new Ray(new Vector3(0,1.37f,0),Vector3.forward)));for(int f=0;f<65;f++)Call(game,"HandShotStep",1/90f);int hits=0;for(int i=0;i<4;i++)if(pool[19+i].hp<1000)hits++;Assert.That(hits,Is.EqualTo(kind==2?2:kind==5?4:3),"Affected targets for "+SurvivorArmory.Get(kind).name);}
  game.meta.equippedWeapon=0;game.StartRun();var target=pool[19];Assert.That((bool)Call(game,"Spawn",target,5));target.go.transform.position=new Vector3(0,1.25f,2);target.hp=1000;var wall=GameObject.CreatePrimitive(PrimitiveType.Cube);wall.layer=RoomNavigation.Layer;wall.transform.position=new Vector3(0,1.3f,1);wall.transform.localScale=new Vector3(1,1,.15f);Physics.SyncTransforms();Assert.That(game.FireHandWeapon(new Ray(new Vector3(0,1.37f,0),Vector3.forward)));for(int f=0;f<50;f++)Call(game,"HandShotStep",1/90f);Assert.That(target.hp,Is.EqualTo(1000),"Hand shot must stop at scanned furniture");Object.DestroyImmediate(wall);
  // Automatic energy bolts also aim at actual flyer height.
  game.player.stacks[(int)UpgradeId.ENERGY_PROJECTILE]=1;target.hp=1000;Call(game,"WeaponStep",1/90f);for(int f=0;f<60;f++)Call(game,"ShotStep",1/90f);Assert.That(target.hp,Is.LessThan(1000));
  Call(game,"UpdateHandVisual");var hand=(Transform)Get(game,"handRoot");Assert.That(hand.gameObject.activeSelf,Is.True);Assert.That(hand.GetChild(0).gameObject.activeSelf,Is.True);var ui=game.GetComponent<SurvivorUI>();var panel=(Canvas)Get(ui,"panel");if(panel)panel.gameObject.SetActive(false);Call(game,"ResetHandCombat",true);Assert.That(game.platform.WeaponPose(out var shotRay,out _));Assert.That(game.FireHandWeapon(shotRay));Call(game,"HandShotStep",.07f);Capture(game,"armory-hand-weapon");game.Menu();yield return new ExitPlayMode();
 }
 [UnityTest]public IEnumerator FlyingCrowdUsesAirSpaceWithoutPassingThroughWalls(){
  EditorSceneManager.OpenScene("Assets/Scenes/SpatialSurvivor.unity");yield return new EnterPlayMode();yield return null;yield return null;var game=Object.FindObjectOfType<SurvivorGame>();game.enabled=false;game.GetComponent<SurvivorUI>().enabled=false;game.StartRun();Set(game,"spawn",100f);Array.Clear(game.player.stacks,0,game.player.stacks.Length);game.player.elapsed=240;Set(game,"completedBosses",1);game.player.damage=0;game.player.maxHealth=game.player.health=100000;var pool=(SurvivorGame.Enemy[])Get(game,"enemies");for(int i=19;i<25;i++)Assert.That((bool)Call(game,"Spawn",pool[i],i<22?5:6));for(int f=0;f<900;f++){game.Step(1/90f);for(int i=19;i<25;i++){Assert.That(game.platform.Navigation.ContainsAir(pool[i].go.transform.position,pool[i].radius),Is.True);for(int j=i+1;j<25;j++)Assert.That(Vector3.Distance(pool[i].go.transform.position,pool[j].go.transform.position),Is.GreaterThanOrEqualTo(pool[i].radius+pool[j].radius+.065f));}}Assert.That(game.player.health,Is.LessThan(100000),"Flying creatures must reach attack range");var positions=new Vector3[6];for(int i=0;i<6;i++)positions[i]=pool[i+19].go.transform.position;var travel=new float[6];for(int f=0;f<180;f++){game.Step(1/90f);for(int i=0;i<6;i++){travel[i]+=Vector3.Distance(positions[i],pool[i+19].go.transform.position);positions[i]=pool[i+19].go.transform.position;}}foreach(float d in travel)Assert.That(d,Is.GreaterThan(.1f),"Airborne crowd keeps moving");game.Menu();yield return new ExitPlayMode();
 }
 static object Get(object target,string field)=>target.GetType().GetField(field,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(target);
 static void Set(object target,string field,object value)=>target.GetType().GetField(field,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(target,value);
 static object Call(object target,string method,params object[] args)=>target.GetType().GetMethod(method,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(target,args);
 static System.Collections.Generic.List<Button> Buttons(SurvivorUI ui)=>(System.Collections.Generic.List<Button>)Get(ui,"buttons");
 static void Capture(SurvivorGame game,string name){var camera=game.platform.Head;var oldTarget=camera.targetTexture;var old=RenderTexture.active;var target=new RenderTexture(1400,1000,24);var pixels=new Texture2D(1400,1000,TextureFormat.RGB24,false);try{Canvas.ForceUpdateCanvases();camera.targetTexture=target;camera.Render();RenderTexture.active=target;pixels.ReadPixels(new Rect(0,0,1400,1000),0,0);pixels.Apply();Directory.CreateDirectory("Docs/Validation");File.WriteAllBytes("Docs/Validation/"+name+".png",pixels.EncodeToPNG());}finally{camera.targetTexture=oldTarget;RenderTexture.active=old;Object.Destroy(target);Object.Destroy(pixels);}}
}
}
